using ArgoBooks.Core.Enums;
using ArgoBooks.Core.Models.Reports;

namespace ArgoBooks.Core.Models.Insights;

/// <summary>
/// Represents the complete insights data generated by the analytics engine.
/// </summary>
public class InsightsData
{
    /// <summary>
    /// Summary statistics for the insights.
    /// </summary>
    public InsightsSummary Summary { get; set; } = new();

    /// <summary>
    /// Forecasted growth metrics.
    /// </summary>
    public ForecastData Forecast { get; set; } = new();

    /// <summary>
    /// Revenue trend insights.
    /// </summary>
    public List<InsightItem> RevenueTrends { get; set; } = [];

    /// <summary>
    /// Detected anomalies.
    /// </summary>
    public List<InsightItem> Anomalies { get; set; } = [];

    /// <summary>
    /// Forecast-related insights.
    /// </summary>
    public List<InsightItem> Forecasts { get; set; } = [];

    /// <summary>
    /// Business recommendations.
    /// </summary>
    public List<InsightItem> Recommendations { get; set; } = [];

    /// <summary>
    /// When the insights were generated.
    /// </summary>
    public DateTime GeneratedAt { get; set; } = DateTime.UtcNow;

    /// <summary>
    /// Whether there is sufficient data to generate meaningful insights.
    /// </summary>
    public bool HasSufficientData { get; set; }

    /// <summary>
    /// Message explaining data insufficiency (if applicable).
    /// </summary>
    public string? InsufficientDataMessage { get; set; }
}

/// <summary>
/// Summary statistics for the insights page.
/// </summary>
public class InsightsSummary
{
    /// <summary>
    /// Total number of insights generated.
    /// </summary>
    public int TotalInsights { get; set; }

    /// <summary>
    /// Number of trends detected.
    /// </summary>
    public int TrendsDetected { get; set; }

    /// <summary>
    /// Number of anomalies detected.
    /// </summary>
    public int AnomaliesDetected { get; set; }

    /// <summary>
    /// Number of opportunities/recommendations.
    /// </summary>
    public int Opportunities { get; set; }

    /// <summary>
    /// Number of months of historical data available.
    /// </summary>
    public int MonthsOfData { get; set; }
}

/// <summary>
/// Forecasted growth data.
/// </summary>
public class ForecastData
{
    /// <summary>
    /// Number of months the forecast period covers (e.g., 0.99 for 30 days, 2.96 for 90 days).
    /// </summary>
    public decimal PeriodMonths { get; set; } = 1;

    /// <summary>
    /// Forecasted revenue for the next period.
    /// </summary>
    public decimal ForecastedRevenue { get; set; }

    /// <summary>
    /// Lower bound of revenue forecast (confidence interval).
    /// </summary>
    public decimal ForecastedRevenueLower { get; set; }

    /// <summary>
    /// Upper bound of revenue forecast (confidence interval).
    /// </summary>
    public decimal ForecastedRevenueUpper { get; set; }

    /// <summary>
    /// Revenue growth percentage.
    /// </summary>
    public decimal RevenueGrowthPercent { get; set; }

    /// <summary>
    /// Forecasted expenses for the next period.
    /// </summary>
    public decimal ForecastedExpenses { get; set; }

    /// <summary>
    /// Lower bound of expenses forecast (confidence interval).
    /// </summary>
    public decimal ForecastedExpensesLower { get; set; }

    /// <summary>
    /// Upper bound of expenses forecast (confidence interval).
    /// </summary>
    public decimal ForecastedExpensesUpper { get; set; }

    /// <summary>
    /// Expense growth percentage (positive means expenses increased).
    /// </summary>
    public decimal ExpenseGrowthPercent { get; set; }

    /// <summary>
    /// Forecasted profit for the next period.
    /// </summary>
    public decimal ForecastedProfit { get; set; }

    /// <summary>
    /// Lower bound of profit forecast (conservative scenario: low revenue, high expenses).
    /// </summary>
    public decimal ForecastedProfitLower { get; set; }

    /// <summary>
    /// Upper bound of profit forecast (optimistic scenario: high revenue, low expenses).
    /// </summary>
    public decimal ForecastedProfitUpper { get; set; }

    /// <summary>
    /// Profit growth percentage.
    /// </summary>
    public decimal ProfitGrowthPercent { get; set; }

    /// <summary>
    /// Expected number of new customers.
    /// </summary>
    public int ExpectedNewCustomers { get; set; }

    /// <summary>
    /// Lower bound of new-customer forecast (conservative scenario).
    /// </summary>
    public int ExpectedNewCustomersLower { get; set; }

    /// <summary>
    /// Upper bound of new-customer forecast (optimistic scenario).
    /// </summary>
    public int ExpectedNewCustomersUpper { get; set; }

    /// <summary>
    /// Customer growth percentage.
    /// </summary>
    public decimal CustomerGrowthPercent { get; set; }

    /// <summary>
    /// Growth percentages for the lower and upper forecast bounds, used to show "vs avg" consistent with
    /// the displayed scenario (Conservative uses the lower bound for revenue/profit/customers and the upper
    /// for expenses; Optimistic is the inverse).
    /// </summary>
    public decimal RevenueGrowthPercentLower { get; set; }
    public decimal RevenueGrowthPercentUpper { get; set; }
    public decimal ExpenseGrowthPercentLower { get; set; }
    public decimal ExpenseGrowthPercentUpper { get; set; }
    public decimal ProfitGrowthPercentLower { get; set; }
    public decimal ProfitGrowthPercentUpper { get; set; }
    public decimal CustomerGrowthPercentLower { get; set; }
    public decimal CustomerGrowthPercentUpper { get; set; }

    /// <summary>
    /// Confidence score for the predictions (0-100).
    /// </summary>
    public double ConfidenceScore { get; set; }

    /// <summary>
    /// Confidence level description (Low, Medium, High).
    /// </summary>
    public string ConfidenceLevel { get; set; } = "Medium";

    /// <summary>
    /// Number of months of data used for forecasting.
    /// </summary>
    public int DataMonthsUsed { get; set; }

    /// <summary>
    /// The forecasting method used (e.g., "Combined (SSA + Holt-Winters)").
    /// </summary>
    public string? ForecastMethod { get; set; }

    /// <summary>
    /// Historical accuracy percentage based on past forecasts (0-100).
    /// Null if no validated forecasts exist yet.
    /// </summary>
    public double? HistoricalAccuracyPercent { get; set; }

    /// <summary>
    /// Description of historical forecast accuracy.
    /// </summary>
    public string? AccuracyDescription { get; set; }

    /// <summary>
    /// Number of past forecasts that have been validated against actuals.
    /// </summary>
    public int ValidatedForecastCount { get; set; }

    /// <summary>
    /// Detected seasonal pattern information.
    /// </summary>
    public SeasonalPatternInfo? SeasonalInfo { get; set; }
}

/// <summary>
/// Simplified seasonal pattern info for display in UI.
/// </summary>
public class SeasonalPatternInfo
{
    /// <summary>
    /// Whether a significant seasonal pattern was detected.
    /// </summary>
    public bool HasSeasonalPattern { get; set; }

    /// <summary>
    /// Strength of the seasonal pattern (0-1).
    /// </summary>
    public double Strength { get; set; }

    /// <summary>
    /// Human-readable description of the pattern.
    /// </summary>
    public string Description { get; set; } = string.Empty;

    /// <summary>
    /// The detected trend direction.
    /// </summary>
    public string TrendDirection { get; set; } = "Stable";
}

/// <summary>
/// Represents a single insight item.
/// </summary>
public class InsightItem
{
    /// <summary>
    /// Title of the insight.
    /// </summary>
    public string Title { get; set; } = string.Empty;

    /// <summary>
    /// Detailed description of the insight.
    /// </summary>
    public string Description { get; set; } = string.Empty;

    /// <summary>
    /// Optional recommendation for action.
    /// </summary>
    public string? Recommendation { get; set; }

    /// <summary>
    /// Severity/importance level (Info, Warning, Success, Critical).
    /// </summary>
    public InsightSeverity Severity { get; set; } = InsightSeverity.Info;

    /// <summary>
    /// Category of the insight.
    /// </summary>
    public InsightCategory Category { get; set; }

    /// <summary>
    /// The metric value associated with this insight.
    /// </summary>
    public decimal? MetricValue { get; set; }

    /// <summary>
    /// The percentage change associated with this insight.
    /// </summary>
    public decimal? PercentageChange { get; set; }

    /// <summary>
    /// Whether this insight has an actionable recommendation.
    /// </summary>
    public bool HasRecommendation => !string.IsNullOrEmpty(Recommendation);
}

/// <summary>
/// Display scenario for the forecast cards.
/// Conservative shows the lower bound (revenue/profit/customers) and upper bound (expenses).
/// Baseline shows the point forecast. Optimistic is the inverse of Conservative.
/// </summary>
public enum ForecastScenario
{
    Conservative = 0,
    Baseline = 1,
    Optimistic = 2
}

/// <summary>
/// Severity levels for insights.
/// </summary>
public enum InsightSeverity
{
    /// <summary>Informational insight (blue).</summary>
    Info,

    /// <summary>Positive insight (green).</summary>
    Success,

    /// <summary>Warning that needs attention (orange/yellow).</summary>
    Warning,

    /// <summary>Critical issue requiring immediate action (red).</summary>
    Critical
}

/// <summary>
/// Categories for insights.
/// </summary>
public enum InsightCategory
{
    /// <summary>Revenue-related trends.</summary>
    RevenueTrend,

    /// <summary>Expense-related trends.</summary>
    ExpenseTrend,

    /// <summary>Anomaly detection.</summary>
    Anomaly,

    /// <summary>Forecasting insights.</summary>
    Forecast,

    /// <summary>Business recommendations.</summary>
    Recommendation,

    /// <summary>Customer-related insights.</summary>
    Customer,

    /// <summary>Product-related insights.</summary>
    Product,

    /// <summary>Invoice/payment insights.</summary>
    Payment,

    /// <summary>Inventory-related insights.</summary>
    Inventory
}

/// <summary>
/// Date range for analysis.
/// </summary>
public class AnalysisDateRange
{
    /// <summary>
    /// Start date of the analysis period.
    /// </summary>
    public DateTime StartDate { get; set; }

    /// <summary>
    /// End date of the analysis period.
    /// </summary>
    public DateTime EndDate { get; set; }

    /// <summary>
    /// Name of the date preset (if applicable).
    /// </summary>
    public string? PresetName { get; set; }

    /// <summary>
    /// Creates a custom date range.
    /// </summary>
    public static AnalysisDateRange Custom(DateTime start, DateTime end)
    {
        return new AnalysisDateRange
        {
            StartDate = start,
            EndDate = end,
            PresetName = DateRangePreset.CustomRange.GetDisplayName()
        };
    }

    /// <summary>
    /// The range a date preset covers, keeping the preset's name so trends compare it against the
    /// same period the dashboard does.
    /// </summary>
    public static AnalysisDateRange FromPreset(string presetName, DateTime? earliestDate = null)
    {
        var (start, end) = DatePresetNames.GetDateRange(presetName, earliestDate);
        return new AnalysisDateRange
        {
            StartDate = start,
            EndDate = end,
            PresetName = presetName
        };
    }

    /// <summary>
    /// Gets the number of days in this range.
    /// </summary>
    public int DayCount => (EndDate - StartDate).Days + 1;
}
